// SocratesQ — Cyrillic-capable PDF font (DejaVu Sans, subset to Latin + Cyrillic).
// Loaded on demand only when a PDF is exported, so it doesn't weigh down page loads.
// jsPDF's built-in helvetica has no Cyrillic glyphs, which is why Russian dialogues
// came out as garbage before this font is registered.
window.SQ_PDF_FONT_B64 = "";

window.sqRegisterPdfFont = function(doc) {
  try {
    doc.addFileToVFS('DejaVuSans.ttf', window.SQ_PDF_FONT_B64);
    doc.addFont('DejaVuSans.ttf', 'DejaVuSans', 'normal');
    return 'DejaVuSans';
  } catch (e) {
    return null; // caller falls back to helvetica (Latin-only)
  }
};
